SELECT jsonb_build_object('customer',(SELECT count(*) FROM app.customer_profiles WHERE id='73292b10-226f-5588-920d-cb9421f6e358'),'command',(SELECT count(*) FROM platform.runtime_command_receipt WHERE id IN ('ba56c4f9-896b-59ab-b5c3-a069abea651c','75d4281f-07b5-519e-a789-0bbb7c465540')), 'history',(SELECT count(*) FROM app.customer_profile_lifecycle_event WHERE customer_profile_id='73292b10-226f-5588-920d-cb9421f6e358'),'evidence',(SELECT count(*) FROM platform.owner_mutation_evidence WHERE aggregate_kind='CustomerProfile' AND aggregate_id='73292b10-226f-5588-920d-cb9421f6e358'),'outbox',(SELECT count(*) FROM platform.runtime_outbox_message WHERE command_receipt_id IN ('ba56c4f9-896b-59ab-b5c3-a069abea651c','75d4281f-07b5-519e-a789-0bbb7c465540')),'track_enrollments',(SELECT count(*) FROM app.track_enrollment_receipt WHERE profile_id='73292b10-226f-5588-920d-cb9421f6e358'),'coherent',EXISTS(SELECT 1 FROM app.customer_profiles c
 JOIN platform.runtime_command_receipt q ON q.id='ba56c4f9-896b-59ab-b5c3-a069abea651c' AND q.owner_module_id='customer_buyer_profile' AND q.operation='SH-004.v1'
  AND q.subject_scope='CustomerProfile:'||c.id::text AND q.semantic_key='customer-controls-worker-source-customer' AND q.fingerprint='f34efd94602f54843149268de669019090fcd31cde1deae687b4e76216458c24'
  AND q.state='committed' AND q.source_revision=0 AND q.result_schema_id='SH-004.v1#/$defs/response' AND q.result_schema_version='1'
  AND q.result_body='{"contract":"SH-004.v1","requestId":"worker-source-customer","status":"ok","value":{"customerProfileId":"73292b10-226f-5588-920d-cb9421f6e358","userId":"367c1331-a35d-56e5-871d-e6ade24d9900","lifecycle":"active","sourceToken":"0","receipt":{"owner":"customer_buyer_profile","id":"ba56c4f9-896b-59ab-b5c3-a069abea651c","semanticKey":"customer-controls-worker-source-customer","fingerprint":"f34efd94602f54843149268de669019090fcd31cde1deae687b4e76216458c24","sourceToken":"0","recordedAt":"2026-11-17T00:00:00Z"}}}'::jsonb AND q.result_digest=encode(sha256(convert_to(q.result_body::text,'UTF8')),'hex')
 JOIN app.customer_profile_lifecycle_event h ON h.id='24465100-1a22-5d4b-af74-bf9219510d2a' AND h.customer_profile_id=c.id AND h.command_receipt_id=q.id
  AND h.source_revision=0 AND h.from_status IS NULL AND h.to_status=c.status AND h.actor_user_id=c.user_id AND h.name='customer.lifecycle_changed.v1'
 JOIN platform.owner_mutation_evidence e ON e.id='b63dd17f-18a7-5df7-aca9-cea4b51e20df' AND e.command_receipt_id=q.id AND e.owner_module_id=q.owner_module_id
  AND e.aggregate_kind='CustomerProfile' AND e.aggregate_id=c.id::text AND e.previous_revision IS NULL AND e.committed_revision=0
  AND e.action=q.operation AND e.decision_ref='customer-controls-v1' AND e.evidence_schema_version='1'
  AND e.evidence_schema_id='urn:workinants:database-review:owner-evidence:v1#/$defs/CustomerProfile'
  AND e.evidence_body='{"schema":"database-owner-evidence.v1","owner":"customer_buyer_profile","model":"CustomerProfile","primaryKey":{"id":"73292b10-226f-5588-920d-cb9421f6e358"},"prior":null,"committed":{"id":"73292b10-226f-5588-920d-cb9421f6e358","userId":"367c1331-a35d-56e5-871d-e6ade24d9900","status":"active","revision":"0","privacyGeneration":"0"},"decisionRef":"customer-controls-v1"}'::jsonb AND e.evidence_digest=encode(sha256(convert_to(e.evidence_body::text,'UTF8')),'hex')
 WHERE c.id='73292b10-226f-5588-920d-cb9421f6e358' AND c.user_id='367c1331-a35d-56e5-871d-e6ade24d9900' AND c.status='active' AND c.revision=0 AND c.privacy_generation=0
  AND c.display_name IS NULL AND c.avatar_media_id IS NULL AND c.city IS NULL AND c.state IS NULL AND c.country IS NULL AND c.archived_at IS NULL
  AND q.mutation_transaction_id=c.mutation_transaction_id AND h.mutation_transaction_id=c.mutation_transaction_id AND e.mutation_transaction_id=c.mutation_transaction_id
  AND (SELECT count(*) FROM platform.runtime_outbox_message o WHERE o.command_receipt_id=q.id AND o.producer_owner=q.owner_module_id
   AND o.aggregate_kind='CustomerProfile' AND o.aggregate_id=c.id::text AND o.source_revision=0 AND o.source_generation=0 AND o.schema_version='1'
   AND o.causation_id=q.id::text AND o.correlation_id='worker-source-customer' AND o.mutation_transaction_id=c.mutation_transaction_id
