   AND ((o.id='a20266e7-e5cd-57a8-807f-2c0b56cdd241' AND o.ordinal=0 AND o.kind='event' AND o.name='customer.lifecycle_changed.v1'
    AND o.payload_schema_id='urn:workin-ants:types:v1#/$defs/EventPayload_customer_lifecycle_changed_v1' AND o.payload='{"eventName":"customer.lifecycle_changed.v1","customerProfileId":"73292b10-226f-5588-920d-cb9421f6e358","userId":"367c1331-a35d-56e5-871d-e6ade24d9900","lifecycleRevision":"0","safeState":"active"}'::jsonb)
    OR (o.id='d5eb5e25-5254-52b6-9309-cb9ff22950fb' AND o.ordinal=1 AND o.kind='command' AND o.name='assignDefaultFreeTrack.v1'
    AND o.payload_schema_id='urn:workinants:database-review:foundation-payloads:v1#/$defs/assignDefaultFreeTrackCustomerCommand' AND o.payload='{"sourceOwner":"customer_buyer_profile","userId":"367c1331-a35d-56e5-871d-e6ade24d9900","track":"customer","customerProfileId":"73292b10-226f-5588-920d-cb9421f6e358","sourceCreationRevision":"0","sourceCreationReceipt":"ba56c4f9-896b-59ab-b5c3-a069abea651c","semanticKey":"customer_buyer_profile/73292b10-226f-5588-920d-cb9421f6e358/default-free-enrollment/v1"}'::jsonb)))=2));
